(function () {
  var hint = document.getElementById('hint');
  function say(t) { hint.textContent = t; }
  var cur = getCurrentMessageId();
  // 开场选择器：同一楼的三个开场是三个 swipe，点名字切过去
  var chips = document.querySelectorAll('.chip[data-i]');
  Array.prototype.forEach.call(chips, function (b) {
    b.onclick = function () {
      setChatMessages([{ message_id: cur, swipe_id: Number(b.getAttribute('data-i')) }])
        .catch(function (e) { say(e.message); });
    };
  });
  // 状态栏：chat 变量记你递过几块石头，message 变量记这一幕来过几次
  function paint() {
    var chat = getVariables({ type: 'chat' });
    var here = getVariables({ type: 'message', message_id: cur });
    var n = chat['石头'] || 0;
    document.getElementById('stones').textContent = n;
    document.getElementById('mood').textContent = n >= 3 ? '藏不住的高兴' : (n > 0 ? '有点开心' : '平静');
    document.getElementById('seen').textContent = here['来过'] > 1 ? '第 ' + here['来过'] + ' 次来' : '第一次来';
  }
  var visits = (getVariables({ type: 'message', message_id: cur })['来过'] || 0) + 1;
  insertOrAssignVariables({ '来过': visits }, { type: 'message', message_id: cur });
  document.getElementById('give').onclick = function () {
    updateVariablesWith(function (v) { v['石头'] = (v['石头'] || 0) + 1; return v; }, { type: 'chat' });
    paint();
  };
  // 选项：替你发一句话并让白石回（第一次会先问你）
  Array.prototype.forEach.call(document.querySelectorAll('.opt'), function (b) {
    b.onclick = function () {
      triggerSlash('/send ' + b.getAttribute('data-say') + '|/trigger')
        .then(function () { say('发出去了。'); }, function (e) { say(e.message); });
    };
  });
  paint();
  say('点上面的地名换开场；下面的选项会替你说一句。');
})();
</script></body></html>
```

